#pragma once
/**
 * @file ZwdCarry.hpp
 * @brief The wet-delay carry family (B9): the diagonal or coupling prior and the unconditional Z-row capture.
 *
 * A family file of PASS B's station build: the steps of the family in
 * kStationBuildSteps / kStationCarrySteps (network/assembly/StationBuild.hpp), generated by
 * scripts/nom_pb1b_cut.py from the frozen text of networkPassB_'s produce loop.
 *
 * The harvest half (generated by scripts/nom_hv1_cut.py, checked by
 * scripts/nom_hv1_verify.py) is the family's post-solve harvest, stash and prune, called by
 * networkHarvestLocalCarries (network/carry/LocalCarryHarvest.hpp, its table of contents).
 */

#include <cstdint>
#include <cstddef>
#include <vector>

namespace GnssProcessor {

struct NetworkRunEndView;

// ---- PASS B station steps, declarations (generated by scripts/nom_pb1b_cut.py) ----

struct StationBuild;                       // network/assembly/StationBuild.hpp
struct StationCarryFrame;                  // network/assembly/StationBuild.hpp
enum class StationStep : std::uint8_t;     // network/assembly/StationBuild.hpp

/**
 * @brief The unconditional Z-row capture of a snapshot-armed run (section 17 finding 3).
 *
 * Step `zwd_capture` of kStationBuildSteps (network/assembly/StationBuild.hpp); its kinds: none
 * (it records only). It returns at once unless `zwd_capture && !R.pl_zwd_present`. Records:
 * pl_zwd, pl_zwd_present. The frozen text of networkPassB_'s produce loop below its bindings
 *.
 * @param build One station's build: the station and its slot writable, the run read only.
 * @return StationStep::Next.
 */
StationStep networkZwdRowCapture(StationBuild& build);

/**
 * @brief The ZWD carry (B9): a diagonal prior or a coupling row on the wet delay.
 *
 * Step `zwd` of kStationCarrySteps (network/assembly/StationBuild.hpp); its kinds: PriorZwdCarry,
 * CouplingScalar. It returns at once unless the frozen enclosing conditions legacy_local_inject
 * and `zwd_on || zwd_seam_live`. Records: pl_zwd*, pl_blk_zwd_fallback_diag, prm_zwd_gap_skip.
 * The frozen text of networkPassB_'s produce loop below its bindings.
 * @param carry The station's carry frame (the build, the priors, the coupling builder, the
 *              block columns).
 */
void networkZwdCarryPrior(StationCarryFrame& carry);

// ---- End of the PASS B station steps, declarations ----

// ---- Harvest half, declarations (generated by scripts/nom_hv1_cut.py) ----

struct NetworkRun;                          // network/driver/Run.hpp
struct NetworkEpoch;                        // network/driver/Epoch.hpp
struct HarvestBorder;                       // network/carry/LocalCarryHarvest.hpp
struct StationHarvestBlock;                 // network/carry/LocalCarryHarvest.hpp

/**
 * @brief B9: the ZWD posterior (carry, live seam window, or capture-only for the snapshot), its
 *        prior-residual row, the post-resume census, the stash and F3 row, the prune, the seam
 *        window step.
 *
 * @param run The run: its context (carry, counters, knobs), setup (stations) and engines.
 * @param ep This epoch after the solve (the solution, the assembly, the columns and the clock are
 *           read; nothing is written).
 * @param border This harvest's shared border (column identities, datum-frame covariance, the clone
 *               and shared-history handles).
 * @param blocks Every station's harvest layout, by station index (ok false: not harvested).
 */
void networkHarvestZwd(NetworkRun& run, const NetworkEpoch& ep, HarvestBorder& border,
                       const std::vector<StationHarvestBlock>& blocks);

/**
 * @brief network.zwd_seam_reseed: count the window's folds, advance its retirement clock and log
 *        the decoupling edge.
 *
 * @param run The run: its context (carry, counters, knobs), setup (stations) and engines.
 * @param ep This epoch after the solve (the solution, the assembly, the columns and the clock are
 *           read; nothing is written).
 */
void networkZwdSeamWindowStep(NetworkRun& run, const NetworkEpoch& ep);

// ---- End of the harvest half, declarations ----

/**
 * @brief Run-end report: the seam-scoped ZWD re-seed.
 *
 * The seam-scoped ZWD re-seed (network.zwd_seam_reseed): folds and skips.
 *
 * Gate: prints under `config_.networkZwdSeamReseed()`.
 *
 * @param v The run at its end (network/runend/RunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkZwdSeamRunEnd(const NetworkRunEndView& v);

/// @brief Run-scope counters of ZwdCarry, a base of NetworkServiceCounters (network/state/RunContext.hpp).
struct ZwdCarryCounters {

    // Siblings on the same gap predicate, for other carries (departures).
    long long n_cr_zwd_gap_prune      = 0;  ///< ZWD carry entries dropped by the pl_max_gap_s prune

    // --- Seam-scoped ZWD re-seed (network.zwd_seam_reseed) ---
    // On-path telemetry (standing invariant #4): 0 folds under an armed knob means the
    // window never armed (no warm resume, or no restored Z rows) or every fold was
    // skipped; check the resume log line as well.
    long long n_zwd_seam_folds        = 0;  ///< station-fold count inside the post-resume window
    long long n_zwd_seam_epochs       = 0;  ///< epochs inside the window with >= 1 fold
};

} // namespace GnssProcessor
